#!/usr/bin/env python3
"""Generate Biomedical Research Landscape 2024-2026 HTML Report"""

import pandas as pd
import numpy as np
import json
import base64
from io import BytesIO
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
from matplotlib.patches import FancyBboxPatch
import matplotlib.ticker as mticker
import warnings
warnings.filterwarnings('ignore')

# ── Color palette ──────────────────────────────────────────────────────────────
C_NAVY   = '#1a2b4a'
C_TEAL   = '#0e7c86'
C_BLUE   = '#2563eb'
C_AMBER  = '#d97706'
C_GREEN  = '#16a34a'
C_RED    = '#dc2626'
C_GRAY   = '#64748b'
C_LIGHT  = '#f1f5f9'
C_WHITE  = '#ffffff'
PALETTE  = [C_NAVY, C_TEAL, C_BLUE, C_AMBER, C_GREEN, C_RED, '#7c3aed', '#db2777', '#0891b2', '#65a30d']

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'axes.spines.top': False,
    'axes.spines.right': False,
    'axes.facecolor': C_WHITE,
    'figure.facecolor': C_WHITE,
    'axes.grid': True,
    'grid.color': '#e2e8f0',
    'grid.linewidth': 0.6,
    'axes.titlesize': 13,
    'axes.labelsize': 11,
})

# ── Load & prep data ────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['country_norm'] = df['country'].str.strip()
df.loc[df['country_norm'] == 'United States', 'country_norm'] = 'USA'
df.loc[df['country_norm'] == 'PR China', 'country_norm'] = 'China'

def simplify_type(rt):
    rt = str(rt)
    if 'Systematic Review' in rt: return 'Systematic Review'
    if 'Case Report' in rt or 'Case Reports' in rt: return 'Case Report'
    if 'Review' in rt: return 'Review'
    if 'Preprint' in rt: return 'Preprint'
    if 'Journal Article' in rt: return 'Journal Article'
    return 'Other'

df['simple_type'] = df['research_type'].apply(simplify_type)
SAMPLE_N = len(df)
SOURCE_N = 126832

MONTH_LABELS = {1:'Jan',2:'Feb',3:'Mar',4:'Apr',5:'May',6:'Jun',
                7:'Jul',8:'Aug',9:'Sep',10:'Oct',11:'Nov',12:'Dec'}

def fig_to_b64(fig, dpi=140):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor=C_WHITE)
    plt.close(fig)
    return 'data:image/png;base64,' + base64.b64encode(buf.getvalue()).decode()


# ══════════════════════════════════════════════════════════════════════════════
# CHART 1 – Monthly publication volume (2024-2026)
# ══════════════════════════════════════════════════════════════════════════════
df_known = df[df['pub_month_num'] != 0].copy()

monthly_all = []
for yr in [2024, 2025, 2026]:
    for mn in range(1, 13):
        cnt = len(df_known[(df_known['pub_year']==yr) & (df_known['pub_month_num']==mn)])
        monthly_all.append({'year': yr, 'month': mn, 'label': f"{MONTH_LABELS[mn]}-{yr}", 'count': cnt})
monthly_df = pd.DataFrame(monthly_all)
# trim 2026 to Mar only
monthly_df = monthly_df[~((monthly_df['year']==2026) & (monthly_df['month']>3))]

fig, ax = plt.subplots(figsize=(14, 4.5))
colors_bar = [C_NAVY if r.year==2024 else C_TEAL if r.year==2025 else C_AMBER
              for _, r in monthly_df.iterrows()]
bars = ax.bar(range(len(monthly_df)), monthly_df['count'], color=colors_bar, alpha=0.9, width=0.75)

tick_positions = list(range(len(monthly_df)))
tick_labels = monthly_df['label'].tolist()
ax.set_xticks(tick_positions)
ax.set_xticklabels(tick_labels, rotation=55, ha='right', fontsize=7.5)
ax.set_ylabel('Publications (indexed months)', fontsize=10)
ax.set_title('Monthly Publication Volume — Indexed Records (Jan 2024 – Mar 2026)', fontsize=13, fontweight='bold', color=C_NAVY)

# Vertical separators between years
for sep_x in [11.5, 23.5]:
    ax.axvline(sep_x, color=C_GRAY, lw=1, linestyle='--', alpha=0.5)
ax.text(5.5, ax.get_ylim()[1]*0.92, '2024', fontsize=10, color=C_NAVY, fontweight='bold', ha='center')
ax.text(18, ax.get_ylim()[1]*0.92, '2025', fontsize=10, color=C_TEAL, fontweight='bold', ha='center')
ax.text(26, ax.get_ylim()[1]*0.92, '2026*', fontsize=10, color=C_AMBER, fontweight='bold', ha='center')

legend_patches = [mpatches.Patch(color=C_NAVY, label='2024'),
                  mpatches.Patch(color=C_TEAL, label='2025'),
                  mpatches.Patch(color=C_AMBER, label='2026 (Jan–Mar)')]
ax.legend(handles=legend_patches, loc='upper right', fontsize=9)
fig.tight_layout()
CHART_MONTHLY = fig_to_b64(fig)


# ══════════════════════════════════════════════════════════════════════════════
# CHART 2 – Year totals bar
# ══════════════════════════════════════════════════════════════════════════════
year_counts = df.groupby('pub_year').size()
fig, ax = plt.subplots(figsize=(6, 4))
bars = ax.bar(['2024', '2025', '2026\n(Jan–Mar)'], year_counts.values,
              color=[C_NAVY, C_TEAL, C_AMBER], alpha=0.9, width=0.5)
for bar, val in zip(bars, year_counts.values):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 30,
            f'{val:,}', ha='center', va='bottom', fontsize=11, fontweight='bold', color=C_NAVY)
ax.set_ylabel('Publications (sample)', fontsize=10)
ax.set_title('Total Publications by Year\n(sample: n=4,886)', fontsize=12, fontweight='bold', color=C_NAVY)
ax.set_ylim(0, year_counts.max() * 1.15)
fig.tight_layout()
CHART_YEAR = fig_to_b64(fig)


# ══════════════════════════════════════════════════════════════════════════════
# CHART 3 – Open Access rate over time (monthly, rolling)
# ══════════════════════════════════════════════════════════════════════════════
oa_m = df_known.groupby(['pub_year','pub_month_num'])['open_access'].agg(['sum','count']).reset_index()
oa_m['rate'] = oa_m['sum'] / oa_m['count'] * 100
oa_m['period'] = oa_m['pub_year'] * 100 + oa_m['pub_month_num']
oa_m = oa_m.sort_values('period')
oa_m['label'] = oa_m.apply(lambda r: f"{MONTH_LABELS[int(r.pub_month_num)]}-{int(r.pub_year)}", axis=1)
oa_m = oa_m[~((oa_m['pub_year']==2026) & (oa_m['pub_month_num']>3))]

fig, ax = plt.subplots(figsize=(13, 4.2))
ax.plot(range(len(oa_m)), oa_m['rate'], color=C_TEAL, lw=2.2, marker='o', markersize=5, alpha=0.9)
ax.fill_between(range(len(oa_m)), oa_m['rate'], alpha=0.12, color=C_TEAL)
ax.axhline(65, color=C_GRAY, lw=1, linestyle='--', alpha=0.6, label='65% reference')
ax.set_xticks(range(len(oa_m)))
ax.set_xticklabels(oa_m['label'], rotation=55, ha='right', fontsize=7.5)
ax.set_ylabel('Open Access Rate (%)', fontsize=10)
ax.set_ylim(0, 110)
ax.set_title('Open Access Rate by Month (2024–2026)', fontsize=13, fontweight='bold', color=C_NAVY)
ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f%%'))
for sep_x in [11.5, 23.5]:
    ax.axvline(sep_x, color=C_GRAY, lw=1, linestyle='--', alpha=0.4)
ax.legend(fontsize=9)
fig.tight_layout()
CHART_OA_TIME = fig_to_b64(fig)


# ══════════════════════════════════════════════════════════════════════════════
# CHART 4 – Top 10 countries
# ══════════════════════════════════════════════════════════════════════════════
top_c = df[df['country_norm'] != 'Unknown']['country_norm'].value_counts().head(10)
fig, ax = plt.subplots(figsize=(9, 5))
bars = ax.barh(top_c.index[::-1], top_c.values[::-1], color=PALETTE[:10][::-1], alpha=0.9)
for bar, val in zip(bars, top_c.values[::-1]):
    ax.text(bar.get_width() + 10, bar.get_y() + bar.get_height()/2,
            f'{val:,}', va='center', fontsize=9, color=C_NAVY)
ax.set_xlabel('Publications', fontsize=10)
ax.set_title('Top 10 Countries by Publication Count\n(sample n=4,886; "Unknown" excluded)', fontsize=12, fontweight='bold', color=C_NAVY)
ax.set_xlim(0, top_c.max() * 1.12)
fig.tight_layout()
CHART_COUNTRY = fig_to_b64(fig)


# ══════════════════════════════════════════════════════════════════════════════
# CHART 5 – Country share evolution
# ══════════════════════════════════════════════════════════════════════════════
year_totals = df.groupby('pub_year').size()
country_year = df[df['country_norm'] != 'Unknown'].groupby(['pub_year','country_norm']).size().unstack(fill_value=0)
