    border-radius: 0 8px 8px 0;
    padding: 14px 18px;
    margin: 16px 0;
    font-size: 14px;
    color: #1e40af;
  }}
  .insight strong {{ color: var(--navy); }}
  /* ── Alert / warning box ── */
  .note-box {{
    background: #fffbeb;
    border: 1px solid #fcd34d;
    border-radius: 8px;
    padding: 13px 16px;
    font-size: 13px;
    color: #92400e;
    margin: 16px 0;
  }}
  /* ── Takeaways ── */
  .takeaway-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 18px;
    margin-top: 20px;
  }}
  .takeaway-card {{
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 22px 20px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.06);
  }}
  .takeaway-card .tnum {{
    font-size: 28px;
    font-weight: 900;
    opacity: 0.12;
    color: var(--navy);
    display: block;
    margin-bottom: -4px;
  }}
  .takeaway-card h3 {{
    font-size: 15px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 8px;
  }}
  .takeaway-card p {{
    font-size: 13.5px;
    color: #334155;
    line-height: 1.6;
  }}
  .tag {{
    display: inline-block;
    padding: 2px 9px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
    margin-right: 6px;
    margin-bottom: 6px;
  }}
  .tag-policy {{ background: #dbeafe; color: #1e40af; }}
  .tag-trend {{ background: #d1fae5; color: #065f46; }}
  .tag-risk {{ background: #fee2e2; color: #991b1b; }}
  /* ── Data table ── */
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
    margin-top: 8px;
  }}
  th {{
    background: var(--navy);
    color: var(--white);
    padding: 10px 13px;
    text-align: left;
    font-weight: 600;
  }}
  td {{
    padding: 9px 13px;
    border-bottom: 1px solid var(--border);
  }}
  tr:nth-child(even) td {{ background: var(--light); }}
  tr:hover td {{ background: #e0f2fe; }}
  /* ── Footer ── */
  .footer {{
    text-align: center;
    padding: 32px 24px;
    font-size: 12px;
    color: var(--gray);
    border-top: 1px solid var(--border);
    margin-top: 60px;
  }}
  /* ── Methodology ── */
  .methodology {{
    background: var(--light);
    border-radius: 12px;
    padding: 20px 24px;
    font-size: 13px;
    color: #475569;
    margin-bottom: 20px;
  }}
  .methodology h4 {{ color: var(--navy); margin-bottom: 10px; font-size: 14px; }}
  .methodology ul {{ padding-left: 18px; }}
  .methodology li {{ margin-bottom: 5px; }}
</style>
</head>
<body>

<!-- COVER -->
<div class="cover">
  <div class="cover-tag">Strategic Intelligence Briefing</div>
  <h1>Biomedical Research Landscape<br>2024–2026</h1>
  <p class="subtitle">
    A comprehensive trend analysis of 126,832 biomedical research abstracts indexed in PubMed,
    examining temporal publication patterns, geographic contributions, dominant research topics,
    and open-access adoption.
  </p>
  <div class="cover-meta">
    <span>Audience: Research Policy Analysts &amp; Funding Strategists</span>
    <span>Data Source: PubMed / NCBI · Kaggle</span>
    <span>Coverage: January 2024 – March 2026</span>
    <span>Published: April 2026</span>
  </div>
</div>

<div class="container">

  <!-- DATA NOTE -->
  <div class="note-box" style="margin-top:28px;">
    <strong>Data note:</strong> The analysis is based on a representative sample of <strong>4,886 records</strong>
    drawn from the full 126,832-record PubMed dataset. All percentages and rates are computed from this sample.
    Absolute counts cited in this report should be interpreted as proportional estimates, not exact totals from the
    full corpus. Temporal comparisons account for the natural PubMed indexing lag that concentrates older records
    in 2024 (≈80.3% of sample).
  </div>

  <!-- KPI STRIP -->
  <div class="kpi-strip">
    <div class="kpi-card">
      <span class="kpi-value">126,832</span>
      <span class="kpi-label">Total PubMed Records</span>
      <div class="kpi-sub">Sample analysed: 4,886</div>
    </div>
    <div class="kpi-card">
      <span class="kpi-value">{oa_rate_overall:.1f}%</span>
      <span class="kpi-label">Overall Open Access Rate</span>
      <div class="kpi-sub">2024: {oa_2024:.1f}% · 2025: {oa_2025:.1f}%</div>
    </div>
    <div class="kpi-card">
      <span class="kpi-value">{int(median_authors)}</span>
      <span class="kpi-label">Median Authors / Article</span>
      <div class="kpi-sub">Collaboration proxy (IQR 4–9)</div>
    </div>
    <div class="kpi-card">
      <span class="kpi-value">{top10_share:.1f}%</span>
      <span class="kpi-label">Top 10 Countries Share</span>
      <div class="kpi-sub">China + USA alone: ~31%</div>
    </div>
    <div class="kpi-card">
      <span class="kpi-value">52.9%</span>
      <span class="kpi-label">MeSH-Indexed Records</span>
      <div class="kpi-sub">Newer 2025–2026 records lag indexing</div>
    </div>
    <div class="kpi-card">
      <span class="kpi-value">27</span>
      <span class="kpi-label">Months of Coverage</span>
      <div class="kpi-sub">Jan 2024 – Mar 2026</div>
    </div>
  </div>


  <!-- ═══════════════════════════════════════════════════════════════ -->
  <!-- SECTION 1 – Publication Volume & Temporal Distribution         -->
  <!-- ═══════════════════════════════════════════════════════════════ -->
  <div class="section" id="publication-volume-trends">
    <div class="section-header">
      <div class="section-num">1</div>
      <h2>Publication Volume &amp; Temporal Distribution</h2>
    </div>

    <div class="methodology">
      <h4>Analytical framing</h4>
      <ul>
        <li>The 2024 dominance (80.3% of sample: 3,924 records) reflects PubMed's real-world indexing lag — publications accumulate more indexed entries as time passes.</li>
        <li>2025 (737 records; 15.1%) and 2026 (225 records; 4.6%, Jan–Mar only) are structurally under-represented and should be benchmarked on <em>rates</em>, not raw counts.</li>
        <li>Within 2024, 575 records (14.7%) have unknown publication month; 179 records in 2025 similarly lack month data. These are excluded from the monthly chart.</li>
      </ul>
    </div>

    <div class="two-col">
      <div class="chart-wrap">
        <img src="{CHART_YEAR}" alt="Year totals">
        <p class="chart-caption"><strong>Fig 1a.</strong> Raw record counts by year in the 4,886-record sample.
        The strong 2024 skew is an indexing artifact, not evidence of declining research output.</p>
      </div>
      <div style="display:flex;flex-direction:column;gap:16px;">
        <div class="insight">
          <strong>Indexing lag effect:</strong> January 2024 alone accounts for 1,665 indexed records (42.5% of all 2024 month-known records) — likely because many late-2023 / early-2024 publications completed full indexing during this window.
        </div>
        <div class="insight">
          <strong>2025 trajectory:</strong> Despite the smaller raw count, 2025 shows a consistent monthly baseline of ~30–94 indexed records. December 2025 (94 records) is the highest month of that year, suggesting end-of-year processing batch effects.
        </div>
        <div class="insight">
          <strong>2026 early signal:</strong> March 2026 (98 records) already exceeds the 2025 monthly average (61.4), pointing to continued growth in biomedical research output.
        </div>
      </div>
    </div>

    <div class="chart-wrap" style="margin-top:8px;">
      <img src="{CHART_MONTHLY}" alt="Monthly volume 2024-2026">
      <p class="chart-caption"><strong>Fig 1b.</strong> Month-by-month indexed publication counts.
      The dramatic January 2024 spike (1,665 records) reflects batch indexing of older records.
      Records with unknown publication month (575 in 2024; 179 in 2025) are excluded.
      2026 data ends at March. Dashed vertical lines mark year boundaries.</p>
    </div>

    <div class="note-box">
      <strong>Analytical caution:</strong> The steep 2024-to-2025 count decline is an artifact of indexing completeness, not a real-world decline in biomedical research activity. When comparing across years, normalize to monthly rates and use OA/type ratios rather than raw counts.
    </div>
  </div>


  <!-- ═══════════════════════════════════════════════════════════════ -->
  <!-- SECTION 2 – Geographic Landscape                               -->
  <!-- ═══════════════════════════════════════════════════════════════ -->
  <div class="section" id="geographic-landscape">
    <div class="section-header">
      <div class="section-num">2</div>
      <h2>Geographic Landscape of Biomedical Research</h2>
    </div>

    <div class="two-col">
      <div class="chart-wrap">
        <img src="{CHART_COUNTRY}" alt="Top 10 countries">
        <p class="chart-caption"><strong>Fig 2a.</strong> Top 10 contributing countries by total indexed publications
        (144 "Unknown" country records excluded). China and USA combined account for ~31% of the sample.</p>
      </div>
      <div class="chart-wrap">
        <img src="{CHART_COUNTRY_TREND}" alt="Country share over time">
        <p class="chart-caption"><strong>Fig 2b.</strong> Year-over-year country share (% of all indexed records).
        China's share dips in 2025 then recovers in early 2026. India's share rises notably in 2025 (3.3% → 8.0%),
        suggesting accelerating Indian research output or improved indexing coverage.</p>
      </div>
    </div>

    <div class="insight">
      <strong>China's dominance:</strong> With 1,028 records (normalized), China contributes approximately 22.6% of 2024 publications, 13.2% in 2025, and 20.4% in 2026 — consistently the top single-nation contributor. The 2025 dip likely reflects indexing lag for Chinese-language journals that translates to PubMed later.
    </div>
    <div class="insight">
      <strong>India's emergence:</strong> India's share nearly triples from 3.3% (2024) to 8.0% (2025), the largest proportional shift among major contributors. This warrants attention for funding strategists tracking research partnerships and citation networks.
    </div>

    <div style="margin-top:24px;">
      <h3 style="font-size:16px;font-weight:700;color:var(--navy);margin-bottom:14px;">
        Top 10 Country Summary Table
      </h3>
      <div class="chart-wrap" style="padding:16px;">
        <table>
          <thead><tr>
            <th>Country</th><th>2024</th><th>2025</th><th>2026 (Jan–Mar)</th><th>Total</th><th>Median Authors</th>
          </tr></thead>
          <tbody>
"""

# Inject country table
top_countries_list = [c for c in df['country_norm'].value_counts().head(11).index if c != 'Unknown'][:10]
country_year_data = df[df['country_norm'] != 'Unknown'].groupby(['pub_year','country_norm']).size().unstack(fill_value=0)
country_med = df.groupby('country_norm')['authors_count'].median()

for ctry in top_countries_list:
    c24 = int(country_year_data.loc[2024, ctry]) if 2024 in country_year_data.index else 0
    c25 = int(country_year_data.loc[2025, ctry]) if 2025 in country_year_data.index else 0
    c26 = int(country_year_data.loc[2026, ctry]) if 2026 in country_year_data.index else 0
    ctotal = c24 + c25 + c26
    cmed = country_med.get(ctry, 0)
    html += f"            <tr><td><strong>{ctry}</strong></td><td>{c24}</td><td>{c25}</td><td>{c26}</td><td>{ctotal}</td><td>{int(cmed)}</td></tr>\n"

html += f"""          </tbody>
        </table>
      </div>
    </div>
  </div>


  <!-- ═══════════════════════════════════════════════════════════════ -->
  <!-- SECTION 3 – Research Topic & MeSH Keyword Analysis             -->
  <!-- ═══════════════════════════════════════════════════════════════ -->
  <div class="section" id="topic-and-mesh-analysis">
    <div class="section-header">
      <div class="section-num">3</div>
      <h2>Research Topic &amp; MeSH Keyword Analysis</h2>
    </div>

    <div class="note-box">
      <strong>Coverage note:</strong> Only 52.9% of sample records have a <code>major_topic</code> assigned. Newer 2025–2026 publications are under-indexed due to MeSH indexing lag (MeSH assignment typically occurs weeks to months after initial PubMed indexing). Year-over-year topic comparisons should be treated as directional signals, not definitive volume counts.
    </div>

    <div class="two-col">
      <div class="chart-wrap">
        <img src="{CHART_TOPICS}" alt="Top 20 major topics">
        <p class="chart-caption"><strong>Fig 3a.</strong> Top 20 major MeSH topics by total occurrence. COVID-19 remains
        the leading single topic (43 records), followed by Type 2 Diabetes and Breast Neoplasms.</p>
      </div>
      <div class="chart-wrap">
        <img src="{CHART_KW}" alt="Top 15 substantive MeSH keywords">
        <p class="chart-caption"><strong>Fig 3b.</strong> Top 15 substantive MeSH keywords (demographic/species terms excluded).
        Retrospective and cross-sectional study designs dominate, reflecting observational research norms.
        COVID-19 remains highly prevalent as a keyword even beyond its 2020–2022 peak.</p>
      </div>
    </div>

    <div class="insight">
      <strong>Disease areas dominating:</strong> COVID-19, Type 2 Diabetes, Breast Neoplasms, and Alzheimer Disease head the major topic list — chronic disease burden and pandemic aftermath continue to drive research prioritization globally.
    </div>
    <div class="insight">
      <strong>Microbiome on the rise:</strong> Gastrointestinal Microbiome ranks 4th overall with 16 records. Given that MeSH indexing lags for newer records, the actual volume of gut microbiome research is likely higher than this count suggests.
    </div>
    <div class="insight">
      <strong>AI / digital health signal:</strong> Keywords such as "Algorithms" (47), "Signal Processing, Computer-Assisted" (26), and "Deep Learning" (appearing in major topics) indicate growing computational and AI-driven research, though raw counts remain modest in this sample.
    </div>

    <h3 style="font-size:16px;font-weight:700;color:var(--navy);margin:24px 0 14px;">Top Major Topics by Year</h3>
    <div class="chart-wrap" style="padding:16px;">
      <table>
        <thead><tr><th>Major Topic</th><th>2024</th><th>2025</th><th>2026 (Jan–Mar)</th><th>Total</th></tr></thead>
        <tbody>
"""

# Inject topic table
df_topic_all = df[df['major_topic'].notna() & (df['major_topic'] != '')]
topic_by_year = df_topic_all.groupby(['major_topic','pub_year']).size().unstack(fill_value=0)
top_t = df_topic_all['major_topic'].value_counts().head(15).index
for t in top_t:
    t24 = int(topic_by_year.loc[t, 2024]) if 2024 in topic_by_year.columns and t in topic_by_year.index else 0
    t25 = int(topic_by_year.loc[t, 2025]) if 2025 in topic_by_year.columns and t in topic_by_year.index else 0
    t26 = int(topic_by_year.loc[t, 2026]) if 2026 in topic_by_year.columns and t in topic_by_year.index else 0
    html += f"          <tr><td><strong>{t}</strong></td><td>{t24}</td><td>{t25}</td><td>{t26}</td><td>{t24+t25+t26}</td></tr>\n"

html += f"""        </tbody>
      </table>
    </div>
    <p class="chart-caption" style="margin-top:8px;">
      <strong>Interpretation note:</strong> Low 2025–2026 counts for many topics reflect incomplete MeSH indexing of recent publications, not genuine topic disappearance. COVID-19's apparent decline (37 → 5 from 2024 to 2025) is partly a real research shift and partly an indexing artifact.
    </p>
  </div>


  <!-- ═══════════════════════════════════════════════════════════════ -->
  <!-- SECTION 4 – Open Access Adoption & Journal Landscape           -->
  <!-- ═══════════════════════════════════════════════════════════════ -->
  <div class="section" id="open-access-patterns">
    <div class="section-header">
      <div class="section-num">4</div>
      <h2>Open Access Adoption &amp; Journal Landscape</h2>
    </div>

    <div class="two-col">
      <div class="chart-wrap">
        <img src="{CHART_OA_YEAR}" alt="OA rate by year">
        <p class="chart-caption"><strong>Fig 4a.</strong> Open access rate by publication year.
        2025 records show the highest OA rate (74.1%), consistent with global policy trends toward mandated open access.
        The 2026 rate (53.8%) is lower, likely because recently indexed articles include more subscription-based
        journals not yet archived in PMC.</p>
      </div>
      <div class="chart-wrap">
        <img src="{CHART_OA_COUNTRY}" alt="OA rate by country">
        <p class="chart-caption"><strong>Fig 4b.</strong> Open access rates for the top 8 contributing countries.
        Iran leads at 86.9%, reflecting heavy reliance on open-access mega-journals.
        China's 55.7% rate is the lowest among major contributors — a strategic consideration for international
        citation visibility and policy alignment.</p>
      </div>
    </div>

    <div class="chart-wrap">
      <img src="{CHART_OA_TIME}" alt="OA rate over time">
      <p class="chart-caption"><strong>Fig 4c.</strong> Monthly open access rate trajectory (Jan 2024 – Mar 2026).
      Note high volatility in months with small sample sizes (e.g., Oct 2024: 42 records; Aug 2025: 26 records).
      The dashed reference line marks the 65% threshold. March 2026 shows a notable drop (23.5%) — this outlier
      likely reflects a batch of recently indexed subscription-journal articles not yet available via PMC.</p>
    </div>

    <div class="insight">
      <strong>Overall OA rate: {oa_rate_overall:.1f}%</strong> — nearly two-thirds of all indexed biomedical abstracts in this sample are accessible via PubMed Central. This is substantially above pre-2020 industry benchmarks (~40%) and reflects the impact of NIH, Wellcome Trust, and Plan S mandates.
    </div>

    <div class="chart-wrap" style="margin-top:8px;">
      <img src="{CHART_JOURNALS}" alt="Top 10 journals">
      <p class="chart-caption"><strong>Fig 4d.</strong> Top 10 journals by indexed volume.
      <em>Scientific Reports</em> (82), <em>Heliyon</em> (76), and <em>Cureus</em> (69) lead — all mega-journals with high OA rates and broad scope, reinforcing the OA publication trend. The IEEE EMBC conference proceedings (46) indicates significant biomedical engineering cross-over research.</p>
    </div>
  </div>


  <!-- ═══════════════════════════════════════════════════════════════ -->
  <!-- SECTION 5 – Research Type Distribution & Collaboration         -->
  <!-- ═══════════════════════════════════════════════════════════════ -->
  <div class="section" id="research-type-collaboration">
    <div class="section-header">
      <div class="section-num">5</div>
      <h2>Research Type Distribution &amp; Collaboration Indicators</h2>
    </div>

    <div class="two-col">
      <div class="chart-wrap">
        <img src="{CHART_RT}" alt="Research type donut">
        <p class="chart-caption"><strong>Fig 5a.</strong> Research type distribution across the full sample.
        Journal Articles dominate (84.5%). Reviews (8.3%), Case Reports (4.2%), Systematic Reviews (1.7%),
        and Preprints (0.8%) make up the remainder.</p>
      </div>
      <div class="chart-wrap">
        <img src="{CHART_AUTHORS}" alt="Median authors by type">
        <p class="chart-caption"><strong>Fig 5b.</strong> Median author count by research type.
        Preprints have the highest median (9 authors), consistent with large collaborative bioRxiv submissions.
        Case Reports (5) and Reviews (5) reflect lower collaboration norms.</p>
      </div>
    </div>

    <div class="insight">
      <strong>Preprint signal:</strong> Although preprints represent only 0.8% of records (41 articles), all are open access (100% OA rate) and have the highest median author count (9). This signals that high-collaboration, cutting-edge research is increasingly shared pre-publication.
    </div>
    <div class="insight">
      <strong>Systematic Reviews:</strong> At only 1.7% of the sample (85 records) but with a 56.5% OA rate — the lowest among research types — there is a policy gap for mandating open access of high-impact synthesis publications.
    </div>

    <h3 style="font-size:16px;font-weight:700;color:var(--navy);margin:24px 0 14px;">Research Type Breakdown Table</h3>
    <div class="chart-wrap" style="padding:16px;">
      <table>
        <thead><tr>
          <th>Research Type</th><th>Count</th><th>% of Sample</th><th>Median Authors</th><th>OA Rate</th>
        </tr></thead>
        <tbody>
"""

rt_tab = df.groupby('simple_type').agg(
    count=('pmid','count'),
    med_auth=('authors_count','median'),
    oa_rate=('open_access','mean')
).reset_index().sort_values('count', ascending=False)

for _, r in rt_tab.iterrows():
    pct = r['count'] / len(df) * 100
    html += f"          <tr><td><strong>{r.simple_type}</strong></td><td>{int(r['count'])}</td><td>{pct:.1f}%</td><td>{int(r.med_auth)}</td><td>{r.oa_rate*100:.1f}%</td></tr>\n"

html += f"""        </tbody>
      </table>
    </div>
  </div>


  <!-- ═══════════════════════════════════════════════════════════════ -->
  <!-- SECTION 6 – Key Takeaways & Strategic Implications             -->
  <!-- ═══════════════════════════════════════════════════════════════ -->
  <div class="section" id="key-takeaways">
    <div class="section-header">
      <div class="section-num">6</div>
      <h2>Key Takeaways &amp; Strategic Implications</h2>
    </div>

    <div class="note-box" style="margin-bottom:24px;">
      <strong>Executive summary:</strong> The biomedical research landscape is shifting toward higher open-access publication, growing non-Western contributions (especially India), and continued dominance of chronic disease and pandemic-related topics. Early 2026 data suggests sustained output momentum.
    </div>

    <div class="takeaway-grid">

      <div class="takeaway-card">
        <span class="tnum">01</span>
        <span class="tag tag-policy">Policy</span>
        <h3>Open Access Has Crossed a Structural Threshold</h3>
        <p>With {oa_rate_overall:.1f}% overall OA rate and 74.1% in 2025, open-access publication is now the majority norm in biomedical research. Funders should expect near-universal PMC compliance within 2–3 years. Plan S-aligned institutions should benchmark against the 74%+ level, not the old 40% baseline.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">02</span>
        <span class="tag tag-trend">Trend</span>
        <h3>China &amp; India Are the Key Non-Western Growth Stories</h3>
        <p>China holds a consistent ~20%+ share of indexed biomedical output. India's 2.4× share increase from 2024 to 2025 (3.3% → 8.0%) is the single most notable geographic shift. Strategists building international partnerships should prioritize both countries — particularly for clinical trial and epidemiological studies.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">03</span>
        <span class="tag tag-trend">Trend</span>
        <h3>Chronic Disease &amp; Microbiome Research Are the Core Growth Themes</h3>
        <p>Diabetes, cancer (breast, hepatocellular, lung, renal), neurodegenerative disease (Alzheimer, Parkinson), and gastrointestinal microbiome dominate the topic landscape. These remain the strongest candidates for sustained funding prioritization through 2027.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">04</span>
        <span class="tag tag-policy">Policy</span>
        <h3>Systematic Reviews Face an Open Access Gap</h3>
        <p>Despite being the highest-impact research synthesis format, Systematic Reviews have the lowest OA rate in this sample (56.5%). This is below the 65.1% sample average and well below the Preprint (100%) and Case Report (80.8%) rates. Funders should consider targeted OA mandates for synthesis publications.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">05</span>
        <span class="tag tag-trend">Trend</span>
        <h3>Preprints Signal a High-Collaboration Research Frontier</h3>
        <p>Preprints (all OA, median 9 authors) are the publication format with the highest collaboration intensity. As a leading indicator of incoming peer-reviewed output, monitoring preprint servers — especially bioRxiv — provides a 6–12 month forward view on emerging research priorities.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">06</span>
        <span class="tag tag-risk">Data Risk</span>
        <h3>Indexing Lag Systematically Distorts Year-Over-Year Comparisons</h3>
        <p>The 2024 dominance (80.3% of sample) is a PubMed indexing artifact. Any internal report or dashboard comparing raw 2024 vs. 2025 counts without normalization will generate misleading conclusions about research output trajectory. Rate-based metrics (OA%, type%, country%) are the correct analytical currency.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">07</span>
        <span class="tag tag-trend">Trend</span>
        <h3>Mega-Journals Now Dominate Biomedical Publishing Volume</h3>
        <p><em>Scientific Reports</em>, <em>Heliyon</em>, and <em>Cureus</em> — all broad-scope, high-volume OA mega-journals — are the three most-indexed venues in this dataset. Their rise reflects a structural shift in where biomedical science is published, with implications for impact factor benchmarks and peer-review quality standards.</p>
      </div>

      <div class="takeaway-card">
        <span class="tnum">08</span>
        <span class="tag tag-policy">Policy</span>
        <h3>Early 2026 Data Confirms Continued Output Growth</h3>
